        window.draw(btn);
        sf::Text text(label, font, 20);
        text.setPosition(x + 25, y + 12); window.draw(text);
    }

    void drawBoard() {
        for (int i = 0; i < 8; i++) {
            for (int j = 0; j < 8; j++) {
                sf::RectangleShape square(sf::Vector2f(80, 80));
                square.setPosition(i * 80 + 80, j * 80 + 10);
                square.setFillColor((i + j) % 2 == 0 ? sf::Color(235, 235, 208) : sf::Color(119, 148, 85));
                window.draw(square);
            }
        }
