        while (window.isOpen()) {
            sf::Event event;
            while (window.pollEvent(event)) {
                if (event.type == sf::Event::Closed) window.close();
                if (event.type == sf::Event::MouseButtonPressed) {
                    sf::Vector2i pos = sf::Mouse::getPosition(window);
                    if (pos.y > 670 && pos.y < 720) {
                        if (pos.x > 50 && pos.x < 230) currentState = UIState::BOARD;
                        else if (pos.x > 310 && pos.x < 490) currentState = (currentState == UIState::SETTINGS) ? UIState::BOARD : UIState::SETTINGS;
                        else if (pos.x > 570 && pos.x < 750) currentState = (currentState == UIState::RATINGS) ? UIState::BOARD : UIState::RATINGS;
                    }
                }
            }
            render();
        }
    }
};

